194	function numericKey(x) {
195	  if (typeof x === 'bigint') return 'n�' + x.toString();
196	  // Number: unify integral doubles with the matching int.
197	  if (Number.isFinite(x) && Number.isInteger(x)) return 'n�' + BigInt(x).toString();
198	  if (Number.isNaN(x)) return 'f�nan�' + objectIdOfNaN(x);
199	  if (x === Infinity) return 'f�inf';
200	  if (x === -Infinity) return 'f�-inf';
201	  return 'f�' + x.toString();
202	}
