204	// Each distinct NaN object in a dict stays distinct in CPython because
205	// `nan != nan`; approximate by making every NaN key unique.
206	let nanCounter = 0;
207	const nanIds = new WeakMap();
208	function objectIdOfNaN() {
209	  return 'nan' + ++nanCounter;
210	}
211	
212	let idCounter = 0;
213	const idMap = new WeakMap();
214	/** Stable per-object identity, standing in for CPython's `id()`. */
215	export function objectId(o) {
216	  if (o === null || (typeof o !== 'object' && typeof o !== 'function')) return 'v' + String(o);
217	  let v = idMap.get(o);
218	  if (v === undefined) {
219	    v = ++idCounter;
220	    idMap.set(o, v);
221	  }
222	  return v;
223	}
