229	export class PyDict {
230	  constructor(entries = []) {
231	    /** @type {Map<string, [any, any]>} insertion ordered */
232	    this.map = new Map();
233	    for (const [k, v] of entries) this.set(k, v);
234	  }
235	  get size() {
236	    return this.map.size;
237	  }
238	  has(k) {
239	    return this.map.has(hashKey(k));
240	  }
241	  get(k, dflt = undefined) {
242	    const e = this.map.get(hashKey(k));
243	    return e === undefined ? dflt : e[1];
244	  }
245	  set(k, v) {
246	    const h = hashKey(k);
247	    const e = this.map.get(h);
248	    if (e === undefined) this.map.set(h, [k, v]);
249	    else e[1] = v; // CPython keeps the original key object
250	  }
251	  delete(k) {
252	    return this.map.delete(hashKey(k));
253	  }
254	  /** @returns {Array<[any, any]>} */
255	  entries() {
256	    return Array.from(this.map.values(), (e) => [e[0], e[1]]);
257	  }
258	  keys() {
259	    return Array.from(this.map.values(), (e) => e[0]);
260	  }
261	  values() {
262	    return Array.from(this.map.values(), (e) => e[1]);
263	  }
264	}
