266	export class PySet {
267	  constructor(items = []) {
268	    this.map = new Map();
269	    for (const it of items) this.add(it);
270	  }
271	  get size() {
272	    return this.map.size;
273	  }
274	  add(v) {
275	    const h = hashKey(v);
276	    if (!this.map.has(h)) this.map.set(h, v);
277	  }
278	  has(v) {
279	    return this.map.has(hashKey(v));
280	  }
281	  delete(v) {
282	    return this.map.delete(hashKey(v));
283	  }
284	  values() {
285	    return Array.from(this.map.values());
286	  }
287	  keyOrder() {
288	    return Array.from(this.map.keys());
289	  }
290	}
