321	export function truthy(v) {
322	  if (v instanceof PyBool) return v.value;
323	  if (v instanceof PyNone) return false;
324	  if (typeof v === 'bigint') return v !== 0n;
325	  if (typeof v === 'number') return v !== 0;
326	  if (typeof v === 'string') return v.length > 0;
327	  if (v instanceof PyBytes) return v.bytes.length > 0;
328	  if (v instanceof PyList || v instanceof PyTuple) return v.items.length > 0;
329	  if (v instanceof PySet || v instanceof PyDict) return v.size > 0;
330	  if (v instanceof PyComplex) return v.re !== 0 || v.im !== 0;
331	  if (v instanceof PyRange) return rangeLength(v) > 0n;
332	  return true;
333	}
