351	export function pyEq(a, b) {
352	  if (isNumeric(a) && isNumeric(b)) return numEq(numOf(a), numOf(b));
353	  if (a instanceof PyComplex || b instanceof PyComplex) {
354	    if (!(isNumeric(a) || a instanceof PyComplex) || !(isNumeric(b) || b instanceof PyComplex))
355	      return false;
356	    const ca = a instanceof PyComplex ? a : new PyComplex(toFloat(a), 0);
357	    const cb = b instanceof PyComplex ? b : new PyComplex(toFloat(b), 0);
358	    return ca.re === cb.re && ca.im === cb.im;
359	  }
360	  if (typeof a === 'string' || typeof b === 'string') return a === b;
361	  if (a instanceof PyNone || b instanceof PyNone) return a === b;
362	  if (a instanceof PyBytes && b instanceof PyBytes) {
363	    if (a.bytes.length !== b.bytes.length) return false;
364	    for (let i = 0; i < a.bytes.length; i++) if (a.bytes[i] !== b.bytes[i]) return false;
365	    return true;
366	  }
367	  if (a instanceof PyList && b instanceof PyList) return seqEq(a.items, b.items);
368	  if (a instanceof PyTuple && b instanceof PyTuple) return seqEq(a.items, b.items);
369	  if (a instanceof PySet && b instanceof PySet) {
370	    if (a.size !== b.size) return false;
371	    for (const k of a.keyOrder()) if (!b.map.has(k)) return false;
372	    return true;
373	  }
374	  if (a instanceof PyDict && b instanceof PyDict) {
375	    if (a.size !== b.size) return false;
376	    for (const [k, v] of a.entries()) {
377	      if (!b.has(k)) return false;
378	      if (!pyEq(b.get(k), v)) return false;
379	    }
380	    return true;
381	  }
382	  return a === b;
383	}
