385	function numEq(x, y) {
386	  if (typeof x === 'bigint' && typeof y === 'bigint') return x === y;
387	  if (typeof x === 'number' && typeof y === 'number') return x === y;
388	  // mixed int/float
389	  const bi = typeof x === 'bigint' ? x : y;
390	  const fl = typeof x === 'bigint' ? y : x;
391	  if (!Number.isFinite(fl)) return false;
392	  if (!Number.isInteger(fl)) return false;
393	  return BigInt(fl) === bi;
394	}
