402	/**
403	 * Python `<`-based three-way comparison. Raises TypeError for values that
404	 * CPython refuses to order, which is what makes `sorted()` bail out inside
405	 * PyYAML's representer.
406	 */
407	export function pyCompare(a, b) {
408	  if (isNumeric(a) && isNumeric(b)) return numCompare(numOf(a), numOf(b));
409	  if (typeof a === 'string' && typeof b === 'string') return strCompare(a, b);
410	  if (a instanceof PyBytes && b instanceof PyBytes) {
411	    const x = a.bytes;
412	    const y = b.bytes;
413	    const n = Math.min(x.length, y.length);
414	    for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1;
415	    return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
416	  }
417	  if (a instanceof PyTuple && b instanceof PyTuple) return seqCompare(a.items, b.items);
418	  if (a instanceof PyList && b instanceof PyList) return seqCompare(a.items, b.items);
419	  typeError(
420	    "'<' not supported between instances of '" + typeName(a) + "' and '" + typeName(b) + "'"
421	  );
422	}
