424	function numCompare(x, y) {
425	  if (typeof x === 'bigint' && typeof y === 'bigint') return x < y ? -1 : x > y ? 1 : 0;
426	  const fx = typeof x === 'bigint' ? Number(x) : x;
427	  const fy = typeof y === 'bigint' ? Number(y) : y;
428	  if (Number.isNaN(fx) || Number.isNaN(fy)) return 1; // unordered; keeps sort total
429	  if (typeof x === 'bigint' || typeof y === 'bigint') {
430	    // Compare exactly when one side is a big integer.
431	    if (Number.isFinite(fx) && Number.isFinite(fy) &&
432	        Number.isInteger(fx) && Number.isInteger(fy)) {
433	      const bx = typeof x === 'bigint' ? x : BigInt(fx);
434	      const by = typeof y === 'bigint' ? y : BigInt(fy);
435	      return bx < by ? -1 : bx > by ? 1 : 0;
436	    }
437	  }
438	  return fx < fy ? -1 : fx > fy ? 1 : 0;
439	}
