450	function seqCompare(a, b) {
451	  const n = Math.min(a.length, b.length);
452	  for (let i = 0; i < n; i++) {
453	    if (!pyEq(a[i], b[i])) return pyCompare(a[i], b[i]);
454	  }
455	  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
456	}
