458	/**
459	 * Stable sort that mirrors CPython's "abandon everything on TypeError"
460	 * behaviour: if any comparison raises, the caller sees the PyError and can
461	 * fall back to the original order.
462	 */
463	export function pySorted(items, cmp = pyCompare) {
464	  const arr = items.slice();
465	  const n = arr.length;
466	  if (n < 2) return arr;
467	  // bottom-up stable merge sort
468	  let src = arr;
469	  let dst = new Array(n);
470	  for (let width = 1; width < n; width *= 2) {
471	    for (let lo = 0; lo < n; lo += 2 * width) {
472	      const mid = Math.min(lo + width, n);
473	      const hi = Math.min(lo + 2 * width, n);
474	      let i = lo;
475	      let j = mid;
476	      let k = lo;
477	      while (i < mid && j < hi) {
478	        if (cmp(src[j], src[i]) < 0) dst[k++] = src[j++];
479	        else dst[k++] = src[i++];
480	      }
481	      while (i < mid) dst[k++] = src[i++];
482	      while (j < hi) dst[k++] = src[j++];
483	    }
484	    const t = src;
485	    src = dst;
486	    dst = t;
487	  }
488	  return src;
489	}
