514	/** Split a JS string into an array of single-code-point strings. */
515	export function chars(s) {
516	  const out = [];
517	  for (let i = 0; i < s.length; ) {
518	    const c = s.charCodeAt(i);
519	    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
520	      const d = s.charCodeAt(i + 1);
521	      if (d >= 0xdc00 && d <= 0xdfff) {
522	        out.push(s.slice(i, i + 2));
523	        i += 2;
524	        continue;
525	      }
526	    }
527	    out.push(s[i]);
528	    i += 1;
529	  }
530	  return out;
531	}
