533	/** Python `len()` of a string: number of code points. */
534	export function strLength(s) {
535	  let n = 0;
536	  for (let i = 0; i < s.length; i++, n++) {
537	    const c = s.charCodeAt(i);
538	    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
539	      const d = s.charCodeAt(i + 1);
540	      if (d >= 0xdc00 && d <= 0xdfff) i++;
541	    }
542	  }
543	  return n;
544	}
