565	/** UTF-8 encode a JS string (surrogate pairs handled, lone surrogates -> WTF-8). */
566	export function utf8Encode(s) {
567	  const out = [];
568	  for (const cp of codePoints(s)) {
569	    if (cp < 0x80) out.push(cp);
570	    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
571	    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
572	    else
573	      out.push(
574	        0xf0 | (cp >> 18),
575	        0x80 | ((cp >> 12) & 0x3f),
576	        0x80 | ((cp >> 6) & 0x3f),
577	        0x80 | (cp & 0x3f)
578	      );
579	  }
580	  return new Uint8Array(out);
581	}
